  `search` tinyint(1) DEFAULT '0' COMMENT '当前字段是否作为查询条件',
  `search_condition` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '查询条件',
